useEffect(() => {
  if (!open) return;
  triggerRef.current = document.activeElement;
  dialogRef.current?.focus();

  const onKey = (event) => {
    if (event.key === 'Escape') onClose();
  };
  document.addEventListener('keydown', onKey);

  return () => {
    document.removeEventListener('keydown', onKey);
    triggerRef.current?.focus();
  };
}, [open, onClose]);

